const table=(columns,rows=4)=>`<table class="work-table"><thead><tr>${columns.map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${Array.from({length:rows},()=>'<tr>'+columns.map(()=>'<td>&nbsp;</td>').join('')+'</tr>').join('')}</tbody></table>`;
const formats={C01:'comparison',C02:'measurement',C03:'graph',C04:'measurement',C05:'identification',C06:'sampling',C07:'flows',C08:'flows',C09:'comparison',C10:'niche',C11:'comparison',C12:'graph',C13:'comparison',C14:'niche',C15:'niche',C16:'comparison',C17:'comparison',C18:'graph',C19:'flows',C20:'flows',C21:'flows',C22:'decision',C23:'study',C24:'footprint',C25:'measurement'};
export function lessonFormat(c){return c.format||formats[c.id]||'comparison';}
export function responseLayout(c){const kind=lessonFormat(c),why='<label>Begründung mit Herkunft, Gegenhypothese und verbleibender Unsicherheit<div class="writing"></div></label>';
 if(kind==='graph')return table(['Parameter / Einheit','Kontrolllauf','Vergleich / Eingriff'],3)+'<p>Achsen mit Größen und Einheiten beschriften; eigene Datenpunkte/Kurven eintragen.</p><svg aria-label="Leeres Koordinatensystem zum Eintragen eigener Modelldaten" viewBox="0 0 600 190"><path d="M55 10 V155 H585" fill="none" stroke="#344e40" stroke-width="2"/><path d="M55 50 H585 M55 100 H585 M155 10 V155 M255 10 V155 M355 10 V155 M455 10 V155 M555 10 V155" fill="none" stroke="#cdd4cf"/><text x="260" y="184">Zeit / Faktor und Einheit: __________</text></svg>'+why;
 if(kind==='flows')return '<p>Verbindungsgefüge: Kästen mit Pool/Stoffform beschriften; gerichtete Pfeile mit Prozess, Menge/Einheit und Herkunft. Energiepfeile getrennt markieren.</p><svg aria-label="Leeres Verbindungsgefüge mit fünf beschriftbaren Feldern" viewBox="0 0 600 200">'+[[10,15],[225,15],[440,15],[115,125],[340,125]].map(([x,y])=>`<rect x="${x}" y="${y}" width="150" height="55" rx="4" fill="none" stroke="#52725d"/>`).join('')+'</svg>'+table(['Pool / Bilanzgrenze','Zufluss','Abfluss','Was bleibt offen?'],3)+why;
 if(kind==='decision')return table(['Kriterium / Gewicht','Umleitung','Saisonale Ruhe','Bohlenweg','Beleg / Perspektive'],4)+table(['Sachinformation','Wert / Norm','Folge / Nebenfolge','Unsicherheit'],2)+'<p>Meine Entscheidung, Alternative und Anlass zur späteren Revision:</p><div class="writing"></div>';
 if(kind==='measurement')return table(['Ort / Datum / Methode','Faktor / Einheit oder Skala','Wert / Zeigerzahl','Wiederholung / Unsicherheit'],4)+why;
 if(kind==='identification')return table(['Unbekannter Fund / Ort','Eigene erkennbare Merkmale','Vergleichsalternative','Bestimmung / Gruppe / Grenze'],4)+'<p>Transfer: neuer unbenannter Zweig; welche Merkmale fehlen für die Feinbestimmung?</p><div class="writing"></div>';
 if(kind==='sampling')return table(['Quadrat / Fläche / Tiefe','Einmal gezählte Individuen / Null','Dichte / m²','Auswahlfehler / Wiederholung'],4)+'<p>Mittel, Spannweite und begründete Stichprobenverbesserung:</p><div class="writing"></div>';
 if(kind==='niche')return table(['Organismus / Beleg','Nahrung / Größe','Raum / Tiefe','Zeit / Technik','Überlappung / Unterschied'],5)+why;
 if(kind==='study')return table(['Versuchs-/Kontrollbedingung','Zeit / Konzentration / Einheit','Endpunkt und Ergebnisrichtung','Aussagegrenze / neuer Versuch'],4)+why;
 if(kind==='footprint')return table(['Kategorie / Systemgrenze','Fläche × Faktoren','Teilbetrag / Einheit','Quelle / Jahr / Annahme'],6)+'<p>Summe, Angebotsvergleich, Szenario und Grenzen:</p><div class="writing"></div>';
 return table(['Vergleichsbedingung / Herkunft','Beobachtung / bereitgestellte Information','Funktionshypothese','Alternative / nötige Kontrolle'],4)+why;
}
export function resourceHTML(c,e){return (c.info||[]).map(p=>'<p>'+e(p)+'</p>').join('')+(c.tables||[]).map(t=>'<div class="table-scroll"><table><caption>'+e(t.caption)+'</caption><thead><tr>'+t.columns.map(x=>'<th>'+e(x)+'</th>').join('')+'</tr></thead><tbody>'+t.rows.map(row=>'<tr>'+row.map(x=>'<td>'+e(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>').join('');}
